import type { Skill, SkillCatalog } from "../../types";

export type ReferenceKind = "tool" | "skill" | "block" | "memory";

export interface Reference {
  kind: ReferenceKind;
  /** Referenced entity id (tool name, skill id, ordered-block id, or memory name). */
  target: string;
}

/** Known reference names of the active skill, keyed by the name as authored. */
export type ReferenceIndex = Map<string, Reference>;

export interface TextToken {
  text: string;
  /** What the tag shows; skill tokens display the id without `@skill.`. */
  display?: string;
  reference?: Reference;
}

/**
 * Builds the lookup of names that count as references in the skill's prose,
 * mirroring the compiler's notation: `@skill.<id>` tokens for every catalog
 * skill and `@block.<id>` tokens for the skill's own blocks (both display
 * their bare id; bare skill ids are NOT references and must not highlight).
 * Compiled block flow ids (`<skill_id>__<block_id>`, own or cross-skill),
 * the skill's own bare block ids and its declared tools stay matchable for
 * prose written against the older conventions. On name collisions the more
 * specific kind wins (tool > block > skill).
 */
export function buildReferenceIndex(skill: Skill, catalog: SkillCatalog): ReferenceIndex {
  const index: ReferenceIndex = new Map();
  for (const [skillId, catalogSkill] of Object.entries(catalog)) {
    index.set(`@skill.${skillId}`, { kind: "skill", target: skillId });
    for (const block of Object.values(catalogSkill.blocks)) {
      index.set(block.ordered_block_id, { kind: "block", target: block.ordered_block_id });
    }
  }
  for (const [blockId, block] of Object.entries(skill.blocks)) {
    // The compiler's @block. notation is same-skill only.
    index.set(`@block.${blockId}`, { kind: "block", target: block.ordered_block_id });
    index.set(blockId, { kind: "block", target: block.ordered_block_id });
  }
  for (const toolName of skill.tool_names) {
    index.set(toolName, { kind: "tool", target: toolName });
  }
  return index;
}

/**
 * Builds additional reference entries for @memory mentions in skill prose.
 * Only @-prefixed memory names become pills; bare dotted paths do not.
 * Call this after buildReferenceIndex and merge the result.
 */
export function buildMemoryReferenceIndex(
  memory: Record<string, { value: unknown }> | null | undefined,
): ReferenceIndex {
  const index: ReferenceIndex = new Map();
  if (!memory) return index;
  for (const key of Object.keys(memory)) {
    // Skill prose uses two notations: bare @<key> and the fully-qualified
    // @memory.<key>. Register both so either renders as a pill.
    index.set(`@${key}`, { kind: "memory", target: key });
    index.set(`@memory.${key}`, { kind: "memory", target: key });
  }
  return index;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Splits prose into plain-text and reference tokens.
 *
 * A name only matches as a standalone word: not inside another identifier and
 * not as a segment of a dotted memory path (`session.card_replace.reason`
 * must not highlight the `card_replace` skill). A trailing sentence period
 * still matches (`… hand off to card_disambiguation.`).
 */
export function tokenizeReferences(text: string, index: ReferenceIndex): TextToken[] {
  if (index.size === 0 || text.length === 0) return [{ text }];

  const names = [...index.keys()]
    .sort((left, right) => right.length - left.length)
    .map(escapeRegExp)
    .join("|");
  const pattern = new RegExp(`(?<!\\w)(?<!\\w\\.)(${names})(?!\\w)(?!\\.\\w)`, "g");

  const tokens: TextToken[] = [];
  let cursor = 0;
  for (const match of text.matchAll(pattern)) {
    const matchStart = match.index;
    if (matchStart > cursor) {
      tokens.push({ text: text.slice(cursor, matchStart) });
    }
    const reference = index.get(match[0]);
    tokens.push({
      text: match[0],
      // @-notation tokens (@skill.x, @block.y) display the bare id; other
      // kinds show the matched text as-is.
      display: match[0].startsWith("@") ? match[0].split(".").slice(1).join(".") : undefined,
      reference,
    });
    cursor = matchStart + match[0].length;
  }
  if (cursor < text.length) {
    tokens.push({ text: text.slice(cursor) });
  }
  return tokens;
}
